import subprocess
import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

DNS_SERVER = os.environ.get('DNS_SERVER', '8.8.8.8')
ALLOWED_RECORD_TYPES = ['A', 'AAAA', 'MX', 'CNAME', 'TXT', 'NS', 'SOA']

def validate_domain(domain):
    """Basic domain validation - allows subdomains and wildcards"""
    # Allow alphanumeric, hyphens, dots, and wildcards
    pattern = r'^[a-zA-Z0-9.*_-]+(\.[a-zA-Z0-9_-]+)*$'
    if not re.match(pattern, domain):
        return False
    if len(domain) > 253:
        return False
    return True

def validate_record_type(rtype):
    return rtype.upper() in ALLOWED_RECORD_TYPES

@app.route('/api/dns/lookup', methods=['POST'])
def dns_lookup():
    """Perform DNS lookup using dig command"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    domain = data.get('domain', '')
    record_type = data.get('type', 'A')
    timeout = data.get('timeout', 5)

    # Validate inputs
    if not domain:
        return jsonify({'error': 'domain is required'}), 400

    if not validate_domain(domain):
        return jsonify({'error': 'invalid domain format'}), 400

    if not validate_record_type(record_type):
        return jsonify({'error': f'unsupported record type, use one of {ALLOWED_RECORD_TYPES}'}), 400

    # Ensure timeout is reasonable
    try:
        timeout = int(timeout)
        timeout = max(1, min(timeout, 30))
    except (ValueError, TypeError):
        timeout = 5

    # Build dig command
    # Note: domain is validated above with regex
    cmd = f'dig @{DNS_SERVER} {domain} {record_type} +time={timeout} +tries=1 +short'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout + 5
        )

        output = result.stdout.strip()
        errors = result.stderr.strip()

        response = {
            'domain': domain,
            'type': record_type,
            'results': output.split('\n') if output else [],
            'status': 'success' if result.returncode == 0 else 'error'
        }

        if errors:
            response['warnings'] = errors

        return jsonify(response)

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'DNS lookup timed out'}), 504
    except Exception as e:
        return jsonify({'error': f'lookup failed: {str(e)}'}), 500

@app.route('/api/dns/batch', methods=['POST'])
def batch_lookup():
    """Batch DNS lookups"""
    data = request.get_json()
    domains = data.get('domains', [])
    record_type = data.get('type', 'A')

    if not domains or len(domains) > 20:
        return jsonify({'error': 'provide 1-20 domains'}), 400

    results = []
    for domain in domains:
        if validate_domain(domain) and validate_record_type(record_type):
            cmd = f'dig @{DNS_SERVER} {domain} {record_type} +short +time=3 +tries=1'
            try:
                result = subprocess.run(
                    cmd, shell=True, capture_output=True,
                    text=True, timeout=8
                )
                results.append({
                    'domain': domain,
                    'results': result.stdout.strip().split('\n') if result.stdout.strip() else []
                })
            except:
                results.append({'domain': domain, 'results': [], 'error': 'timeout'})

    return jsonify({'batch_results': results})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
